// node_modules/@neteasecloudmusicapienhanced/api/module/related_playlist.js
var require_related_playlist = __commonJS({
  "node_modules/@neteasecloudmusicapienhanced/api/module/related_playlist.js"(exports2, module2) {
    var { default: axios } = require_axios();
    var createOption = require_option();
    module2.exports = async (query, request) => {
      const res = await axios({
        method: "GET",
        url: `https://music.163.com/playlist?id=${query.id}`
      });
      try {
        const pattern = /<div class="cver u-cover u-cover-3">[\s\S]*?<img src="([^"]+)">[\s\S]*?<a class="sname f-fs1 s-fc0" href="([^"]+)"[^>]*>([^<]+?)<\/a>[\s\S]*?<a class="nm nm f-thide s-fc3" href="([^"]+)"[^>]*>([^<]+?)<\/a>/g;
        let result2, playlists = [];
        while ((result2 = pattern.exec(res.data)) != null) {
          playlists.push({
            creator: {
              userId: result2[4].slice("/user/home?id=".length),
              nickname: result2[5]
            },
            coverImgUrl: result2[1].slice(0, -"?param=50y50".length),
            name: result2[3],
            id: result2[2].slice("/playlist?id=".length)
          });
        }
        res.body = { code: 200, playlists };
        return res;
      } catch (err) {
        res.status = 500;
        res.body = { code: 500, msg: err.stack };
        return Promise.reject(res);
      }
    };
  }
});

