// node_modules/@neteasecloudmusicapienhanced/api/module/register_anonimous.js
var require_register_anonimous = __commonJS({
  "node_modules/@neteasecloudmusicapienhanced/api/module/register_anonimous.js"(exports2, module2) {
    var CryptoJS = require_crypto_js();
    var path = require("path");
    var fs = require("fs");
    var ID_XOR_KEY_1 = "3go8&$8*3*3h0k(2)2";
    var logger = require_logger();
    var createOption = require_option();
    var { generateDeviceId } = require_util();
    function cloudmusic_dll_encode_id(some_id) {
      let xoredString = "";
      for (let i = 0; i < some_id.length; i++) {
        const charCode = some_id.charCodeAt(i) ^ ID_XOR_KEY_1.charCodeAt(i % ID_XOR_KEY_1.length);
        xoredString += String.fromCharCode(charCode);
      }
      const wordArray = CryptoJS.enc.Utf8.parse(xoredString);
      const digest = CryptoJS.MD5(wordArray);
      return CryptoJS.enc.Base64.stringify(digest);
    }
    module2.exports = async (query, request) => {
      const deviceId = generateDeviceId();
      logger.info(`Successfully registered anonimous token, deviceId: ${deviceId}`);
      global.deviceId = deviceId;
      const encodedId = CryptoJS.enc.Base64.stringify(
        CryptoJS.enc.Utf8.parse(
          `${deviceId} ${cloudmusic_dll_encode_id(deviceId)}`
        )
      );
      const data = {
        username: encodedId
      };
      let result2 = await request(
        `/api/register/anonimous`,
        data,
        createOption(query, "xeapi")
      );
      if (result2.body.code === 200) {
        result2 = {
          status: 200,
          body: {
            ...result2.body,
            cookie: result2.cookie.join(";")
          },
          cookie: result2.cookie
        };
      }
      return result2;
    };
  }
});

